import {readyMessage,saveOrderTransition} from '../core/order-actions.js?v=20261111-v15a';
import {configSection,today} from '../core/business.js?v=20261111-v15a';
export function install(ctx){
 const stageFor=q=>configSection(ctx.settings,'production').stages.find(s=>s.key===q.stage)||{key:q.stage,label:q.stage,color:'#64748b'};
 const moneyState=q=>{const f=ctx.orderFinance?.find(f=>f.quote_id===q.id);return {paid:Number(f?.paid||0),pending:Number(f?.pending??q.total)}};
 function stageBadge(q){const s=stageFor(q);return `<span class="stage-badge" style="--stage-color:${s.color}">${ctx.esc(s.label)}</span>`}
 function workflowPage(){const stages=configSection(ctx.settings,'production').stages;ctx.shell(`${ctx.head('Cada pedido, no seu lugar.','Acompanhe aprovação, entrada, produção, entrega e saldo final.','quote','Novo orçamento')}<div class="toolbar"><div class="segmented"><button class="active" id="view-board">Quadro</button><button id="view-list">Lista</button></div><input id="order-search" type="search" aria-label="Buscar pedido" placeholder="Buscar cliente ou número…"><label class="inline-check"><input type="checkbox" id="show-closed"> Mostrar finalizados e cancelados</label><button class="secondary small" id="refresh-board">${ctx.icon('refresh')} Atualizar</button></div><div class="workflow-board-tools" id="board-movement"><span>Mover quadro</span><button type="button" class="secondary small" id="board-left" aria-label="Mover quadro para a esquerda">←</button><div class="board-top-scroll" id="board-top-scroll" tabindex="0" role="region" aria-label="Rolagem horizontal das etapas"><div></div></div><button type="button" class="secondary small" id="board-right" aria-label="Mover quadro para a direita">→</button></div><div id="order-board"></div><p class="muted helper">Arraste um cartão para uma etapa ou abra o pedido para alterar o andamento. Nenhum pagamento é registrado apenas por mover o cartão.</p>`);let mode='board',boardResize;
  function draw(){const previous=ctx.$('.kanban'),position=previous?.scrollLeft||0,columnPositions=new Map([...document.querySelectorAll('.kanban-column')].map(c=>[c.dataset.stage,c.querySelector('.kanban-cards')?.scrollTop||0]));boardResize?.disconnect();const search=ctx.$('#order-search').value.toLowerCase(),closed=ctx.$('#show-closed').checked;const list=ctx.quotes.filter(q=>(closed||!['completed','cancelled'].includes(q.stage))&&(ctx.quoteRef(q)+' '+q.client_snapshot.name).toLowerCase().includes(search));const activeStages=stages.filter(s=>(s.enabled!==false||list.some(q=>q.stage===s.key))&&(closed||!['completed','cancelled'].includes(s.key)));const card=q=>{const f=moneyState(q);return `<article class="order-card" data-order="${q.id}" draggable="${ctx.can('workflow','edit')}" tabindex="0"><div class="card-top"><span>#${ctx.quoteRef(q)}</span><span class="technique">${ctx.esc(q.production?.technique||'A definir')}</span></div><h3>${ctx.esc(q.client_snapshot.name)}</h3><p>${ctx.money(q.total)}</p><div class="order-card-bottom"><span class="${q.delivery_date&&q.delivery_date<today()?'overdue':''}">${ctx.icon('calendar')} ${q.delivery_date?ctx.date(q.delivery_date):'Sem prazo definido'}</span><span class="payment-chip ${f.pending<=0?'paid':''}">${f.pending<=0?'Pago':f.paid>0?'Parcial':'A receber'}</span></div></article>`};
   ctx.$('#order-board').innerHTML=mode==='board'?`<div class="kanban">${activeStages.map(s=>{const orders=list.filter(q=>q.stage===s.key);return `<section class="kanban-column" data-stage="${s.key}" style="--stage-color:${s.color}"><header><span class="stage-dot"></span><h2>${ctx.esc(s.label)}</h2><b>${orders.length}</b></header><div class="column-total">${ctx.money(orders.reduce((n,q)=>n+Number(q.total),0))}</div><div class="kanban-cards">${orders.map(card).join('')||'<div class="column-empty">Nenhum pedido nesta etapa</div>'}</div></section>`}).join('')}</div>`:`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Etapa</th><th>Entrega</th><th>Total</th><th>Recebido</th><th>Saldo</th><th></th></tr></thead><tbody>${list.map(q=>{const f=moneyState(q);return `<tr><td>#${ctx.quoteRef(q)}</td><td>${ctx.esc(q.client_snapshot.name)}</td><td>${stageBadge(q)}</td><td>${q.delivery_date?ctx.date(q.delivery_date):'—'}</td><td>${ctx.money(q.total)}</td><td>${ctx.money(f.paid)}</td><td>${ctx.money(f.pending)}</td><td><button class="secondary small" data-order="${q.id}">Abrir pedido</button></td></tr>`}).join('')}</tbody></table></div></section>`;
   const movement=ctx.$('#board-movement');movement.hidden=mode!=='board';
   if(mode==='board'){const board=ctx.$('.kanban'),top=ctx.$('#board-top-scroll'),spacer=top.firstElementChild;const syncSize=()=>{if(!board.isConnected){boardResize.disconnect();return}spacer.style.width=Math.max(top.clientWidth,board.scrollWidth-board.clientWidth+top.clientWidth)+'px';top.scrollLeft=board.scrollLeft};board.scrollLeft=position;top.onscroll=()=>{board.scrollLeft=top.scrollLeft};board.onscroll=()=>{top.scrollLeft=board.scrollLeft};ctx.$('#board-left').onclick=()=>{board.scrollLeft-=Math.max(255,board.clientWidth*.75)};ctx.$('#board-right').onclick=()=>{board.scrollLeft+=Math.max(255,board.clientWidth*.75)};document.querySelectorAll('.kanban-column').forEach(c=>{c.querySelector('.kanban-cards').scrollTop=columnPositions.get(c.dataset.stage)||0});boardResize=new ResizeObserver(syncSize);boardResize.observe(board);syncSize();}
   document.querySelectorAll('[data-order]').forEach(el=>{el.onclick=()=>orderDialog(el.dataset.order);el.onkeydown=e=>{if(e.key==='Enter')orderDialog(el.dataset.order)};el.ondragstart=e=>{e.dataTransfer.setData('text/plain',el.dataset.order);el.classList.add('dragging')};el.ondragend=()=>el.classList.remove('dragging')});document.querySelectorAll('[data-stage]').forEach(el=>{el.ondragover=e=>{if(ctx.can('workflow','edit')){e.preventDefault();el.classList.add('drop-target')}};el.ondragleave=()=>el.classList.remove('drop-target');el.ondrop=e=>{e.preventDefault();el.classList.remove('drop-target');const id=e.dataTransfer.getData('text/plain');if(ctx.quotes.some(q=>q.id===id))orderDialog(id,el.dataset.stage)}});
  }
  draw();ctx.$('#order-search').oninput=draw;ctx.$('#show-closed').onchange=draw;for(const [id,m]of [['view-board','board'],['view-list','list']])ctx.$('#'+id).onclick=()=>{mode=m;ctx.$('#view-board').classList.toggle('active',m==='board');ctx.$('#view-list').classList.toggle('active',m==='list');draw()};ctx.$('#refresh-board').onclick=async()=>{try{await ctx.load();workflowPage()}catch(e){ctx.toast(e.message)}};
 }
 function readyMessageDialog(id){
  const q=ctx.quotes.find(q=>q.id===id);if(!q)return;
  const budget=configSection(ctx.settings,'budget'),message=readyMessage(budget.ready_message,{cliente:q.client_snapshot.name,pedido:ctx.quoteRef(q),empresa:ctx.settings.company||'Avelon Têxtil',saldo:ctx.money(moneyState(q).pending),entrada_percentual:q.entry_percentage??50});
  const d=ctx.modal('Pedido pronto · mensagem ao cliente',`<p><strong>Pedido #${ctx.esc(ctx.quoteRef(q))}</strong> · ${ctx.esc(q.client_snapshot.name)}</p><label class="field">Mensagem para enviar ao cliente<textarea id="ready-client-message" maxlength="5000" rows="7" style="min-height:180px">${ctx.esc(message)}</textarea></label><p class="muted helper">Você pode ajustar o texto antes de copiar. Depois, cole no WhatsApp, e-mail ou outro aplicativo para enviar ao cliente.</p><p role="status" id="ready-copy-status"></p><div class="form-actions"><button type="button" class="primary" id="copy-ready-message">Copiar mensagem</button>${navigator.share?'<button type="button" class="secondary" id="share-ready-message">Compartilhar mensagem</button>':''}<button type="button" class="secondary" id="retry-ready-stage" hidden>Mover para aguardando saldo</button><button class="secondary" type="button" data-close>Fechar</button></div>`);
  let moving=false;
  async function moveAfterAction(channel){if(moving)return;moving=true;const status=d.querySelector('#ready-copy-status'),retry=d.querySelector('#retry-ready-stage');try{await ctx.rpc('mark_ready_message_action',{p_quote:q.id,p_channel:channel,p_message:d.querySelector('#ready-client-message').value,p_expected:q.updated_at});await ctx.load();if(ctx.current==='workflow')ctx.render('workflow');status.textContent='Mensagem '+(channel==='copy'?'copiada':'compartilhada')+'. Pedido movido para Aguardando saldo.';retry.hidden=true}catch(error){status.textContent='A mensagem foi '+(channel==='copy'?'copiada':'compartilhada')+', mas não foi possível atualizar a etapa: '+error.message;retry.hidden=false;retry.onclick=()=>moveAfterAction(channel)}finally{moving=false}}
  const input=d.querySelector('#ready-client-message');input.addEventListener('copy',e=>{if(e.isTrusted)queueMicrotask(()=>moveAfterAction('copy'))});
  d.querySelector('#copy-ready-message').onclick=async()=>{try{await navigator.clipboard.writeText(input.value);await moveAfterAction('copy')}catch{input.focus();input.select();d.querySelector('#ready-copy-status').textContent='Copie o texto selecionado com Ctrl+C ou pelo menu do aparelho. A etapa será atualizada após a cópia.'}};
  d.querySelector('#share-ready-message')?.addEventListener('click',async e=>{const button=e.currentTarget;button.disabled=true;try{await navigator.share({title:'Pedido #'+ctx.quoteRef(q)+' pronto',text:input.value});await moveAfterAction('share')}catch(error){if(error.name!=='AbortError')d.querySelector('#ready-copy-status').textContent='Não foi possível compartilhar. Use Copiar mensagem para enviar pelo aplicativo de sua preferência.'}finally{button.disabled=false}});

 }
 async function orderDialog(id,stage){const q=ctx.quotes.find(q=>q.id===id);if(!q)return;const cfg=configSection(ctx.settings,'production'),f=moneyState(q),prod=q.production||{},editable=ctx.can('workflow','edit');const d=ctx.modal('Pedido #'+ctx.quoteRef(q),`<div class="order-detail-top"><div><h3>${ctx.esc(q.client_snapshot.name)}</h3>${stageBadge(q)}</div><div><strong>${ctx.money(q.total)}</strong><small>Recebido ${ctx.money(f.paid)} · Saldo ${ctx.money(f.pending)}</small></div></div><form id="order-form"><div class="grid2"><label class="field">Etapa do pedido<select name="stage" ${!editable?'disabled':''}>${cfg.stages.filter(s=>s.enabled!==false||s.key===q.stage).map(s=>`<option value="${s.key}" ${(stage||q.stage)===s.key?'selected':''}>${ctx.esc(s.label)}</option>`).join('')}</select></label>${ctx.field('Entrega prevista','delivery_date','date',q.delivery_date||'',!editable?'disabled':'')}<label class="field">Personalização<select name="technique" ${!editable?'disabled':''}><option value="">A definir</option>${cfg.techniques.map(t=>`<option ${prod.technique===t?'selected':''}>${ctx.esc(t)}</option>`).join('')}</select></label><label class="inline-check"><input type="checkbox" name="art_approved" ${prod.art_approved?'checked':''} ${!editable?'disabled':''}> Arte aprovada pelo cliente</label>${ctx.field('Aprovações do cliente concluídas em','approvals_date','date',prod.approvals_date||'',!editable?'disabled':'')}<p class="note">Informe essa data somente quando o cliente concluir as aprovações. O prazo é estimado em dias úteis até a entrega prevista.</p><label class="field span2">Instruções de produção<textarea name="specifications" maxlength="10000" ${!editable?'disabled':''}>${ctx.esc(prod.specifications||'')}</textarea></label><label class="field span2" id="order-reason-field">Motivo do cancelamento / suspensão<textarea name="note" maxlength="3000" ${!editable?'disabled':''}></textarea></label></div><p class="note">Mover uma etapa não confirma recebimentos. Cancelar ou suspender um pedido também não apaga o histórico financeiro; revise as parcelas e eventuais estornos no Financeiro.</p><p id="order-error" role="alert"></p><div class="form-actions">${ctx.can('quotes','view')?'<button class="secondary" type="button" id="open-proposal">Ver orçamento / PDF</button>':''}${ctx.can('finance','create')?'<button class="secondary" type="button" id="prepare-order">Gerar parcelas</button>':''}${ctx.can('attachments','view')?'<button class="secondary" type="button" id="order-attachments">Anexar / ver comprovantes</button>':''}${q.stage==='ready'?'<button class="secondary" type="button" id="order-ready-message">Mensagem ao cliente</button>':''}${ctx.can('receipts')?'<button class="secondary" type="button" id="order-receipts">Recibos</button>':''}${editable?'<button class="primary" type="submit">Salvar andamento</button>':''}</div></form><section class="history"><h3>Histórico do pedido</h3><div id="order-history">Carregando…</div></section>`,{wide:true});
  const stageInput=d.querySelector('[name="stage"]'),reason=d.querySelector('#order-reason-field'),reasonInput=d.querySelector('[name="note"]');const updateReason=()=>{const needed=['cancelled','suspended'].includes(stageInput.value);reason.hidden=!needed;reasonInput.required=needed;reasonInput.minLength=needed?3:0;reasonInput.disabled=!editable||!needed};stageInput.addEventListener('change',updateReason);updateReason();
  d.querySelector('#order-attachments')?.addEventListener('click',()=>{d.close();ctx.attachmentsDialog('quote',id,'Anexos do pedido #'+ctx.quoteRef(q))});d.querySelector('#order-ready-message')?.addEventListener('click',()=>{d.close();readyMessageDialog(id)});d.querySelector('#order-receipts')?.addEventListener('click',()=>{d.close();ctx.receiptListDialog(id)});d.querySelector('#open-proposal')?.addEventListener('click',()=>{d.close();ctx.openQuote(id)});d.querySelector('#prepare-order')?.addEventListener('click',()=>ctx.receivableDialog(id));
  d.querySelector('#order-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;const data=new FormData(e.target);try{const change={p_quote:id,p_stage:data.get('stage'),p_delivery:data.get('delivery_date')||null,p_production:{...prod,technique:data.get('technique'),specifications:data.get('specifications'),art_approved:data.has('art_approved'),approvals_date:data.get('approvals_date')||null},p_note:['cancelled','suspended'].includes(data.get('stage'))?data.get('note'):'',p_expected:q.updated_at};const result=await saveOrderTransition(ctx,q,change,crypto.randomUUID());if(result.advance){d.close();ctx.productionReceiptDialog(id,change);return}await ctx.load();d.close();if(result.receipt){if(await ctx.showReceipt(result.receipt)!==false){ctx.toast('Pedido finalizado e recibo de quitação pronto para compartilhar.')}else{ctx.render('workflow');const retry=ctx.modal('Recibo final emitido',`<p>O pedido foi finalizado e o recibo foi emitido, mas não foi possível abrir o documento agora. Tente abrir novamente, sem gerar outro recibo.</p><div class="form-actions"><button class="primary" id="retry-final-receipt">Abrir recibo</button><button class="secondary" data-close>Fechar</button></div>`);retry.querySelector('#retry-final-receipt').onclick=async e=>{e.currentTarget.disabled=true;if(await ctx.showReceipt(result.receipt)!==false)retry.close();else if(e.currentTarget.isConnected)e.currentTarget.disabled=false}}return}ctx.render('workflow');if(result.ready&&configSection(ctx.settings,'budget').ready_message_auto!==false){readyMessageDialog(id)}ctx.toast('Andamento atualizado e registrado no histórico.');}catch(err){if(d.isConnected){d.querySelector('#order-error').textContent=err.message;b.disabled=false}else{ctx.toast(err.message)}}};
  try{const events=await ctx.api('/rest/v1/quote_events?quote_id=eq.'+id+'&select=*&order=created_at.desc');d.querySelector('#order-history').innerHTML=events.length?events.map(ev=>`<div class="history-row"><span class="stage-dot" style="--stage-color:#94a3b8"></span><div><strong>${ctx.esc(cfg.stages.find(s=>s.key===ev.next_stage)?.label||ev.next_stage)}</strong><p>${ctx.esc(ev.note||'Etapa atualizada')}</p><small>${new Date(ev.created_at).toLocaleString('pt-BR')}</small></div></div>`).join(''):'<p class="muted">Pedido criado em '+ctx.date(q.created_at)+'. Nenhuma mudança de etapa registrada.</p>'}catch(e){d.querySelector('#order-history').textContent=e.message}
 }
 Object.assign(ctx,{readyMessageDialog,workflowPage,orderDialog,stageBadge,moneyState});
}

